# CORE-03 requirements reference. Stdlib only; no production, test, Recorder or Driver imports.
import copy
import hashlib
import json

ACTOR, ENEMY, SPACE, DOOR = "actor:trial", "actor:sentinel", "space:trial", "object:gate"
PROFILE = "attack:basic"
SEED, BRANCH, STREAM = "0" * 64, "0" * 32, "1" * 32

def canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8")

def frame(*tokens):
    out = bytearray()
    for token in tokens:
        data = token.encode("utf-8")
        out.extend(len(data).to_bytes(4, "big"))
        out.extend(data)
    return bytes(out)

def tagged(tag, doc):
    return hashlib.sha256(frame(tag, canonical(doc).decode("utf-8"))).hexdigest()

def key(kind):
    return {"kind": kind, "version": 1}

def field(owner, unit, minimum=None, maximum=None):
    d = {"owner": owner, "storage": "CORE", "tier": "A", "unit": unit, "scale": 1}
    if minimum is not None:
        d.update(minimum=minimum, maximum=maximum)
    return d

payload_fields = {
 "trial.move": ["dx","dz"],
 "trial.position-delta": ["entity_id","before_cell","after_cell"],
 "trial.position-patch": ["cell"],
 "encounter.interact": ["target_id","option"],
 "encounter.attack": ["target_id","profile_id"],
 "encounter.rest": [],
 "encounter.gate-delta": ["entity_id","before_open","after_open"],
 "encounter.gate-patch": ["is_open"],
 "encounter.hp-delta": ["entity_id","before_hp","after_hp"],
 "encounter.hp-patch": ["hp"],
 "encounter.stamina-delta": ["entity_id","before_stamina","after_stamina"],
 "encounter.stamina-patch": ["value"],
 "encounter.moved": ["actor_id","space_id","from_cell","to_cell"],
 "encounter.move-blocked": ["actor_id","space_id","from_cell","dx","dz","reason"],
 "encounter.gate-changed": ["actor_id","target_id","before_open","after_open"],
 "encounter.attack-resolved": ["actor_id","target_id","profile_id","actor_hp_before","actor_hp_after","target_hp_before","target_hp_after","stamina_before","stamina_after"],
 "encounter.rested": ["actor_id","before_stamina","after_stamina"],
 "encounter.defeated": ["entity_id","killer_id"],
 "encounter.move-cue": ["actor_id","space_id","from_cell","to_cell","from_x_mm","from_z_mm","to_x_mm","to_z_mm","result"],
 "encounter.gate-cue": ["actor_id","target_id","cell","x_mm","z_mm","before_open","after_open"],
 "encounter.attack-cue": ["actor_id","target_id","actor_cell","target_cell","actor_hp_before","actor_hp_after","target_hp_before","target_hp_after","stamina_before","stamina_after","result"],
 "encounter.rest-cue": ["actor_id","before_stamina","after_stamina"],
 "encounter.defeat-cue": ["entity_id","killer_id","cell","x_mm","z_mm"],
}
schema_document = {"version":1,"unknown_fields":"reject","bool_as_integer":"reject","components":[
 {"schema":key("encounter.gate"),"fields":{
  "space_id":field("system.bootstrap","entity_id"),"cell":field("system.bootstrap","cell",4,4),
  "is_open":field("encounter.actions","boolean_integer",0,1)}},
 {"schema":key("encounter.hp"),"fields":{"hp":field("encounter.actions","hp",0,5)}},
 {"schema":key("encounter.stamina"),"fields":{"value":field("encounter.actions","stamina",0,2)}},
 {"schema":key("trial.map"),"fields":{
  "width":field("system.bootstrap","cell_count",3,3),"height":field("system.bootstrap","cell_count",3,3),
  "cell_mm":field("system.bootstrap","mm",1000,1000),
  "blocked_cells":{**field("system.bootstrap","cell",0,8),"collection_cap":1}}},
 {"schema":key("trial.position"),"fields":{
  "space_id":field("system.bootstrap","entity_id"),"cell":field("trial.movement","cell",0,8)}}
], "payloads":[{"schema":key(k),"fields":v} for k,v in sorted(payload_fields.items())]}
rules_document = {"version":1,"actor_id":ACTOR,"enemy_id":ENEMY,"space_id":SPACE,"gate_id":DOOR,
 "width":3,"height":3,"cell_mm":1000,"blocked_cells":[1],"gate_cell":4,"enemy_cell":8,
 "initial_cell":0,"initial_gate_open":0,"initial_actor_hp":3,"initial_enemy_hp":5,"initial_stamina":2,
 "actor_hp_max":3,"enemy_hp_max":5,"stamina_max":2,"attack_profile_id":PROFILE,
 "attack_damage":2,"counter_damage":1,"attack_cost":1,"rest_recovery":1,
 "duration_seconds":1,"cardinal_directions":[[-1,0],[0,-1],[0,1],[1,0]],"reach_cells":1,
 "move_block_priority":["boundary","wall","door","occupied"],
 "counter_only_if_target_survives":True,"counter_only_on_successful_attack":True,
 "defeated_enemy_blocks":False,"dead_actor_admission":"ACTOR_DEFEATED",
 "invalid_attack_range_resources_target_consumes_time":False,
 "repeat_interact_and_full_rest_consume_time":True,
 "derived_life":["alive","defeated"],"derived_stamina":["ready","exhausted"],
 "record_only":True,"rng_purposes":[]}
actions_reads = ["encounter.gate.cell","encounter.gate.is_open","encounter.gate.space_id",
                 "encounter.hp.hp","encounter.stamina.value","trial.position.cell","trial.position.space_id"]
move_reads = ["encounter.gate.cell","encounter.gate.is_open","encounter.gate.space_id","encounter.hp.hp",
              "trial.map.blocked_cells","trial.map.height","trial.map.width","trial.position.cell","trial.position.space_id"]
def node(engine,reads,writes,kinds,emits):
    return {"phase":"RESOLVE","engine_id":engine,"lane":"A","reads":sorted(reads),"writes":sorted(writes),
     "depends_on":[],"action_kinds":[key(k) for k in sorted(kinds)],"on_matching_events":False,
     "every_tick":False,"emits":[key(k) for k in sorted(emits)],"consumes":[],"cost_class":"local"}
schedule_document = {"version":1,"nodes":[
 node("encounter.actions",actions_reads,["encounter.gate.is_open","encounter.hp.hp","encounter.stamina.value"],
      ["encounter.attack","encounter.interact","encounter.rest"],
      ["encounter.attack-resolved","encounter.defeated","encounter.gate-changed","encounter.rested"]),
 node("trial.movement",move_reads,["trial.position.cell"],["trial.move"],
      ["encounter.move-blocked","encounter.moved"])
]}
SCHEMA, RULES, SCHEDULE = (tagged(t,d) for t,d in (
 ("schema/v1",schema_document),("rules/v1",rules_document),("schedule/v1",schedule_document)))
CATALOG = tagged("gameplay-catalog/v1",[])
WORLD = "w1-" + hashlib.sha256(frame("world-id/v1",SEED,RULES,CATALOG)).hexdigest()
pins = {"schema_fingerprint":SCHEMA,"rules_fingerprint":RULES,"schedule_fingerprint":SCHEDULE,
 "rng_version":"sha256-counter-v1","hash_version":"sha256-core-tree-v1",
 "gameplay_catalog_hash":CATALOG,"gameplay_packages":[]}

def components(s):
    def record(kind,entity,fields):
        return {"schema":key(kind),"entity_id":entity,"fields":fields}
    return [
     record("encounter.gate",DOOR,{"space_id":SPACE,"cell":4,"is_open":s["gate"]}),
     record("encounter.hp",ENEMY,{"hp":s["enemy_hp"]}),
     record("encounter.hp",ACTOR,{"hp":s["actor_hp"]}),
     record("encounter.stamina",ACTOR,{"value":s["stamina"]}),
     record("trial.map",SPACE,{"width":3,"height":3,"cell_mm":1000,"blocked_cells":[1]}),
     record("trial.position",ENEMY,{"space_id":SPACE,"cell":8}),
     record("trial.position",ACTOR,{"space_id":SPACE,"cell":s["cell"]})]

def core(s,tick):
    return {"world_id":WORLD,"world_seed_hex":SEED,"tick":tick,"components":components(s),"pending":[],"pins":pins}

def core_hash(doc):
    leaves = [{"schema":c["schema"],"entity_id":c["entity_id"],"hash":tagged("component/v1",c)}
              for c in doc["components"]]
    return tagged("core-root/v1",{**doc,"components":leaves})

def adjacent(a,b):
    return abs(a%3-b%3)+abs(a//3-b//3)==1

def movement(s,dx,dz):
    x,z = s["cell"]%3+dx,s["cell"]//3+dz
    if not(0<=x<3 and 0<=z<3): return s["cell"],"boundary"
    target=z*3+x
    if target==1: return s["cell"],"wall"
    if target==4 and not s["gate"]: return s["cell"],"door"
    if target==8 and s["enemy_hp"]>0: return s["cell"],"occupied"
    return target,"moved"

def attack(a,t,st):
    assert type(a) is int and 1<=a<=3 and type(t) is int and 1<=t<=5 and type(st) is int and 1<=st<=2
    new_t=max(0,t-2)
    return max(0,a-(1 if new_t>0 else 0)),new_t,st-1

def command(seq,rev,kind,payload):
    return {"command_id":f"c1:{BRANCH}:{STREAM}:{seq}","actor_id":ACTOR,"expected_revision":rev,
            "schema":key(kind),"payload":payload}

def event(tick,kind,body,producer,sequence):
    eid="e1-"+hashlib.sha256(frame("event-id/v1",WORLD,str(tick),"RESOLVE","0",producer,str(sequence))).hexdigest()
    return {"header":{"event_id":eid,"type_key":key(kind),"producer_id":producer,"occurred_at":tick,
      "phase":"RESOLVE","wave":0,"producer_rank":0 if producer=="encounter.actions" else 1,
      "sequence":sequence,"caused_by":[],"degraded":[]},"due_tick":tick,"payload":body}

def cues_for(facts,s):
    cues=[]
    for f in facts:
        kind=f["header"]["type_key"]["kind"]
        b=f["payload"]
        if kind in ("encounter.moved","encounter.move-blocked"):
            before=b["from_cell"]
            after=b["to_cell"] if kind=="encounter.moved" else before
            body={"actor_id":ACTOR,"space_id":SPACE,"from_cell":before,"to_cell":after,
             "from_x_mm":before%3*1000,"from_z_mm":before//3*1000,
             "to_x_mm":after%3*1000,"to_z_mm":after//3*1000,
             "result":"moved" if kind=="encounter.moved" else b["reason"]}
            cuekind="encounter.move-cue"
        elif kind=="encounter.gate-changed":
            body={**b,"cell":4,"x_mm":1000,"z_mm":1000}; cuekind="encounter.gate-cue"
        elif kind=="encounter.attack-resolved":
            body={k:v for k,v in b.items() if k!="profile_id"}
            body.update(actor_cell=s["cell"],target_cell=8,
             result="target_defeated" if b["target_hp_after"]==0 else "actor_defeated" if b["actor_hp_after"]==0 else "hit")
            cuekind="encounter.attack-cue"
        elif kind=="encounter.rested":
            body=b.copy(); cuekind="encounter.rest-cue"
        else:
            cell=s["cell"] if b["entity_id"]==ACTOR else 8
            body={**b,"cell":cell,"x_mm":cell%3*1000,"z_mm":cell//3*1000}; cuekind="encounter.defeat-cue"
        eid=f["header"]["event_id"]
        cid="p1-"+hashlib.sha256(frame("cue-id/v1",eid,"encounter.presenter",str(len(cues)))).hexdigest()
        cues.append({"header":{"event_id":cid,"type_key":key(cuekind),"producer_id":"encounter.presenter",
          "occurred_at":f["due_tick"],"phase":"PRESENT","wave":0,"producer_rank":0,"sequence":len(cues),
          "caused_by":[eid],"degraded":[]},"payload":body,"priority":"important","coalesce_policy":"keep_all","coalesce_key":""})
    return cues

def admission(s,kind,p):
    if s["actor_hp"]==0: return "ACTOR_DEFEATED"
    if kind=="encounter.interact":
        if p["target_id"]!=DOOR: return "INVALID_TARGET"
        if p["option"]=="close" and s["cell"]==4: return "TARGET_OCCUPIED"
        if not adjacent(s["cell"],4): return "OUT_OF_RANGE"
    elif kind=="encounter.attack":
        if p["target_id"]!=ENEMY: return "INVALID_TARGET"
        if p["profile_id"]!=PROFILE: return "INVALID_ATTACK_PROFILE"
        if s["enemy_hp"]==0: return "TARGET_DEFEATED"
        if not adjacent(s["cell"],8): return "OUT_OF_RANGE"
        if s["stamina"]==0: return "INSUFFICIENT_STAMINA"
    return None

def resolve(s,cmd,tick):
    kind,p=cmd["schema"]["kind"],cmd["payload"]
    old=copy.deepcopy(s); facts=[]; changes=[]
    def delta(kind,entity,before_key,after_key,before,after):
        if before!=after:
            changes.append({"schema":key(kind),"entity_id":entity,before_key:before,after_key:after})
    if kind=="trial.move":
        s["cell"],result=movement(s,p["dx"],p["dz"])
        if result=="moved":
            body={"actor_id":ACTOR,"space_id":SPACE,"from_cell":old["cell"],"to_cell":s["cell"]}
            facts.append(event(tick,"encounter.moved",body,"trial.movement",0))
            delta("trial.position-delta",ACTOR,"before_cell","after_cell",old["cell"],s["cell"])
        else:
            body={"actor_id":ACTOR,"space_id":SPACE,"from_cell":old["cell"],"dx":p["dx"],"dz":p["dz"],"reason":result}
            facts.append(event(tick,"encounter.move-blocked",body,"trial.movement",0))
    elif kind=="encounter.interact":
        s["gate"]=1 if p["option"]=="open" else 0
        body={"actor_id":ACTOR,"target_id":DOOR,"before_open":old["gate"],"after_open":s["gate"]}
        facts.append(event(tick,"encounter.gate-changed",body,"encounter.actions",0))
        delta("encounter.gate-delta",DOOR,"before_open","after_open",old["gate"],s["gate"])
    elif kind=="encounter.rest":
        s["stamina"]=min(2,s["stamina"]+1)
        body={"actor_id":ACTOR,"before_stamina":old["stamina"],"after_stamina":s["stamina"]}
        facts.append(event(tick,"encounter.rested",body,"encounter.actions",0))
        delta("encounter.stamina-delta",ACTOR,"before_stamina","after_stamina",old["stamina"],s["stamina"])
    else:
        s["actor_hp"],s["enemy_hp"],s["stamina"]=attack(old["actor_hp"],old["enemy_hp"],old["stamina"])
        body={"actor_id":ACTOR,"target_id":ENEMY,"profile_id":PROFILE,
         "actor_hp_before":old["actor_hp"],"actor_hp_after":s["actor_hp"],
         "target_hp_before":old["enemy_hp"],"target_hp_after":s["enemy_hp"],
         "stamina_before":old["stamina"],"stamina_after":s["stamina"]}
        facts.append(event(tick,"encounter.attack-resolved",body,"encounter.actions",0))
        for name,entity in (("actor_hp",ACTOR),("enemy_hp",ENEMY)):
            delta("encounter.hp-delta",entity,"before_hp","after_hp",old[name],s[name])
        delta("encounter.stamina-delta",ACTOR,"before_stamina","after_stamina",old["stamina"],s["stamina"])
        if s["enemy_hp"]==0 or s["actor_hp"]==0:
            entity,killer=(ENEMY,ACTOR) if s["enemy_hp"]==0 else (ACTOR,ENEMY)
            facts.append(event(tick,"encounter.defeated",{"entity_id":entity,"killer_id":killer},"encounter.actions",1))
    changes.sort(key=lambda d:(d["schema"]["kind"].removesuffix("-delta") if d["schema"]["kind"]!="trial.position-delta" else "trial.position",d["entity_id"]))
    return facts,changes

def trace(initial,flow):
    s=copy.deepcopy(initial); tick=revision=high_water=0; receipts=[]
    def protocol():
        return {"branch_id":BRANCH,"revision":revision,"streams":[{"stream_id":STREAM,"actor_id":ACTOR,
         "highest_committed_sequence":high_water,"status":"active"}],"receipts":copy.deepcopy(receipts)}
    initial_core,initial_protocol=core(s,0),protocol()
    header={"world_id":WORLD,"world_seed_hex":SEED,"initial_core_hash":core_hash(initial_core),
     "initial_protocol_hash":tagged("protocol/v1",initial_protocol),"schema_fingerprint":SCHEMA,
     "rules_fingerprint":RULES,"schedule_fingerprint":SCHEDULE,"rng_version":pins["rng_version"],
     "hash_version":pins["hash_version"],"gameplay_packages":[],"build_artifacts":[]}
    steps=[];publications=[];summaries=[]
    for cmd in flow:
        facts=[];cues=[];diagnostics=[];diff=None;code=None
        fingerprint=tagged("command/v1",{k:v for k,v in cmd.items() if k!="command_id"})
        retained=next((r for r in receipts if r["command"]["command_id"]==cmd["command_id"]),None)
        seq=int(cmd["command_id"].split(":")[-1])
        if retained:
            if retained["command"]!=cmd: code="COMMAND_ID_CONFLICT"
            else:
                outcome={"kind":"committed","receipt":copy.deepcopy(retained["receipt"])}
                if retained["receipt"]["revision"]<revision:
                    diagnostics=[{"code":"RESYNC_REQUIRED","message_key":"error.resync_required"}]
        elif seq<=high_water: code="RETRY_WINDOW_EXPIRED"
        elif cmd["expected_revision"]!=revision: code="STALE_REVISION"
        else:
            code=admission(s,cmd["schema"]["kind"],cmd["payload"])
            if code is None:
                previous=revision;revision+=1;tick+=1;high_water=seq
                facts,changes=resolve(s,cmd,tick)
                receipt={"command_id":cmd["command_id"],"previous_revision":previous,
                 "revision":revision,"tick":tick,"core_hash":core_hash(core(s,tick))}
                receipts.append({"command":copy.deepcopy(cmd),"command_fingerprint":fingerprint,"receipt":receipt})
                outcome={"kind":"committed","receipt":receipt}
                diff={"receipt":receipt,"changes":changes}
                cues=cues_for(facts,s)
        if code:
            outcome={"kind":"rejected","failure":{"code":code,"message_key":"error."+code.lower()},"current_revision":revision}
        cd,pd=core(s,tick),protocol()
        steps.append({"command":copy.deepcopy(cmd),"outcome":copy.deepcopy(outcome),"core_hash":core_hash(cd),
         "protocol_hash":tagged("protocol/v1",pd),"facts_hash":tagged("turn-facts/v1",facts),"diff_hash":tagged("turn-diff/v1",diff),
         "witness":{"core":cd,"protocol":pd,"facts":copy.deepcopy(facts),"diff":copy.deepcopy(diff)}})
        publications.append(copy.deepcopy({"outcome":outcome,"facts":facts,"diff":diff,"cues":cues,"diagnostics":diagnostics}))
        summaries.append({"index":len(steps)-1,"state":copy.deepcopy(s),"tick":tick,"revision":revision,
         "result":code or "retry" if retained else code or "committed","fact_count":len(facts),
         "delta_count":len(diff["changes"]) if diff else None,"cue_count":len(cues)})
    return {"format_version":1,"initial_core":initial_core,"initial_protocol":initial_protocol,"trace":{"header":header,"steps":steps}},publications,summaries

def move(seq,rev,dx,dz): return command(seq,rev,"trial.move",{"dx":dx,"dz":dz})
def interact(seq,rev,option): return command(seq,rev,"encounter.interact",{"target_id":DOOR,"option":option})
def hit(seq,rev): return command(seq,rev,"encounter.attack",{"target_id":ENEMY,"profile_id":PROFILE})
def rest(seq,rev): return command(seq,rev,"encounter.rest",{})
initial={"cell":0,"gate":0,"actor_hp":3,"enemy_hp":5,"stamina":2}
flow=[move(1,0,1,0),interact(2,1,"open"),move(2,1,0,1),move(3,2,1,0),
 interact(4,3,"open"),interact(5,4,"open"),move(6,5,1,0),interact(7,6,"close"),
 move(7,6,0,1),move(8,7,1,0),hit(9,8),hit(10,9),hit(11,10),rest(11,10),
 hit(12,11),hit(13,12),move(13,12,1,0),hit(9,8),rest(14,0),
 rest(9,8),rest(14,13),rest(15,14),rest(16,15),interact(17,16,"close")]
expected_fixture,expected_publications,trace_summary=trace(initial,flow)
death_fixture,death_publications,death_summary=trace(
 {"cell":7,"gate":0,"actor_hp":1,"enemy_hp":5,"stamina":2},
 [hit(1,0),rest(2,1),hit(1,0),rest(1,0),move(2,1,1,0)])

movement_vectors=[]
for gate in (0,1):
 for enemy_hp in (0,5):
  for cell in (0,2,3,4,5,6,7,8):
   if (cell==4 and gate==0) or (cell==8 and enemy_hp>0): continue
   for dx,dz in ((-1,0),(0,-1),(0,1),(1,0)):
    s={**initial,"cell":cell,"gate":gate,"enemy_hp":enemy_hp}
    target,result=movement(s,dx,dz)
    movement_vectors.append({"state":s,"dx":dx,"dz":dz,"to_cell":target,"result":result,
      "delta_count":int(result=="moved"),"fact_count":1,"cue_count":1,"tick_increment":1})
attack_vectors=[]
for a in (1,2,3):
 for t in (1,2,3,4,5):
  for st in (1,2):
   aa,tt,ss=attack(a,t,st)
   attack_vectors.append({"actor_hp_before":a,"target_hp_before":t,"stamina_before":st,
    "actor_hp_after":aa,"target_hp_after":tt,"stamina_after":ss,
    "result":"target_defeated" if tt==0 else "actor_defeated" if aa==0 else "hit",
    "delta_count":2+int(aa!=a),"fact_count":1+int(tt==0 or aa==0)})
interaction_vectors=[]
for gate in (0,1):
 for cell in (0,2,3,4,5,6,7,8):
  if cell==4 and not gate: continue
  for option in ("open","close"):
   s={**initial,"cell":cell,"gate":gate,"enemy_hp":0}
   code=admission(s,"encounter.interact",{"target_id":DOOR,"option":option})
   after=gate if code else int(option=="open")
   interaction_vectors.append({"state":s,"option":option,"rejection":code,"gate_after":after,
     "tick_increment":0 if code else 1,"delta_count":None if code else int(after!=gate)})
rest_vectors=[{"before":s,"after":min(2,s+1),"delta_count":int(s<2),"tick_increment":1} for s in (0,1,2)]

wrong=copy.deepcopy(expected_fixture);wrong["trace"]["steps"]=wrong["trace"]["steps"][:7]
last=wrong["trace"]["steps"][-1];w=last["witness"]
w["core"]["components"][6]["fields"]["cell"]=6
last["core_hash"]=core_hash(w["core"])
for r in (last["outcome"]["receipt"],w["protocol"]["receipts"][-1]["receipt"],w["diff"]["receipt"]):
    r["core_hash"]=last["core_hash"]
w["facts"][0]["payload"]["to_cell"]=6;w["diff"]["changes"][0]["after_cell"]=6
for category,tag in (("protocol","protocol/v1"),("facts","turn-facts/v1"),("diff","turn-diff/v1")):
    last[category+"_hash"]=tagged(tag,w[category])
literal_documents=[]
for name,tag,doc in (("schema","schema/v1",schema_document),("rules","rules/v1",rules_document),
 ("schedule","schedule/v1",schedule_document),("initial-core","core-root/v1",expected_fixture["initial_core"])):
    if name=="initial-core": continue
    data=canonical(doc)
    literal_documents.append({"name":name,"tag":tag,"document":doc,"utf8":data.decode(),"utf8_hex":data.hex(),"sha256":tagged(tag,doc)})
result={"schema_document":schema_document,"rules_document":rules_document,"schedule_document":schedule_document,
 "literal_documents":literal_documents,"initial_core_hash":core_hash(expected_fixture["initial_core"]),
 "expected_fixture":expected_fixture,"expected_publications":expected_publications,"trace_summary":trace_summary,
 "expected_fixture_canonical_sha256":hashlib.sha256(canonical(expected_fixture)).hexdigest(),
 "death_fixture":death_fixture,"death_publications":death_publications,"death_summary":death_summary,
 "death_fixture_canonical_sha256":hashlib.sha256(canonical(death_fixture)).hexdigest(),
 "movement_vectors":movement_vectors,"attack_vectors":attack_vectors,
 "interaction_vectors":interaction_vectors,"rest_vectors":rest_vectors,
 "negative_self_consistent_movement_fixture":wrong,
 "negative_expected_first_mismatch":{"step_index":6,"path":"$core.components[6].fields.cell","expected":"6","actual":"4"}}
